// EndDateContainsFold applies the ContainsFold predicate on the "end_date" field.
func EndDateContainsFold(v gartype.Date) predicate.Carplace {
	vc := string(v)
	return predicate.Carplace(sql.FieldContainsFold(FieldEndDate, vc))
}

// IsActualEQ applies the EQ predicate on the "is_actual" field.
func IsActualEQ(v gartype.Flag) predicate.Carplace {
	return predicate.Carplace(sql.FieldEQ(FieldIsActual, v))
}

// IsActualNEQ applies the NEQ predicate on the "is_actual" field.
func IsActualNEQ(v gartype.Flag) predicate.Carplace {
	return predicate.Carplace(sql.FieldNEQ(FieldIsActual, v))
}

// IsActiveEQ applies the EQ predicate on the "is_active" field.
func IsActiveEQ(v gartype.Flag) predicate.Carplace {
	return predicate.Carplace(sql.FieldEQ(FieldIsActive, v))
}

// IsActiveNEQ applies the NEQ predicate on the "is_active" field.
func IsActiveNEQ(v gartype.Flag) predicate.Carplace {
	return predicate.Carplace(sql.FieldNEQ(FieldIsActive, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Carplace) predicate.Carplace {
	return predicate.Carplace(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Carplace) predicate.Carplace {
	return predicate.Carplace(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Carplace) predicate.Carplace {
	return predicate.Carplace(sql.NotPredicates(p))
}
